package pe.edu.grupo4.carga;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class CargaAcademicaIntegrationTest { @Autowired MockMvc mvc;
 private static final String BODY="{\"cicloAcademico\":\"2026-2\",\"docenteId\":1,\"cursoId\":1,\"seccion\":\"A\",\"sedeId\":1,\"diaSemana\":\"MONDAY\",\"horaInicio\":\"18:00\",\"horaFin\":\"20:00\"}";
 @Test void seedCatalogsAllowCreationThenPreventDuplicateSchedule()throws Exception{mvc.perform(get("/api/v1/catalogos")).andExpect(status().isOk()).andExpect(jsonPath("$.sedes.length()").value(4)).andExpect(jsonPath("$.docentes.length()").value(4));mvc.perform(post("/api/v1/cargas-academicas").contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isCreated()).andExpect(jsonPath("$.estado").value("ACTIVA"));mvc.perform(post("/api/v1/cargas-academicas").contentType(MediaType.APPLICATION_JSON).content(BODY)).andExpect(status().isConflict()).andExpect(jsonPath("$.message").value(org.hamcrest.Matchers.containsString("Cruce horario")));}
}
